#!/usr/bin/env python3
import json, re
from pathlib import Path
CH = Path(__file__).parent.parent / 'chapters'
def sections(n):
    md = (CH / ('ch%02d.md' % n)).read_text(encoding='utf-8')
    title = re.match(r'^## 第 \d+ 章　(.*)$', md.splitlines()[0])[1].strip()
    secs = [re.sub(r'^[一二三四五六七八九十]+、', '', s.strip()) for s in re.findall(r'^### (.*)$', md, re.M)]
    wrong = ''
    m = re.search(r'^### 本章怎样算错\s*\n+(.*?)(?=\n### |\Z)', md, re.M | re.S)
    if m: wrong = re.sub(r'\s+', '', m[1].strip())
    return title, [s for s in secs if s not in ('本章怎样算错', '参考与待核')], wrong
tasks = []
for n in range(1, 54):
    t, secs, wrong = sections(n)
    deconstruct = 21 <= n <= 36
    q = '先看本章的小节：%s。读完回答三件事：第一，本章要回答的问题是什么，用你自己的话说一遍；第二，本章哪几处是设想（〔设想〕）、哪几处没有核到原文（〔待核〕），你读到时有没有分清；第三，%s' % (
        '、'.join(secs[:6]),
        '这一派共同立为根基的是什么，共同欠下的是什么，本章的证据够不够这样判？' if deconstruct else '如果把本章的做法放进你手边的一件具体的事里，第一步会是什么？')
    chk = '核对要点：对照本章“本章怎样算错”。' + (wrong[:420] if wrong else '本章章末列有推翻条件。') + ' 这些条件均未检验；〔待核〕未清之前不要当定论引用。'
    tasks.append({'lesson': n, 'name': '第%d章：%s' % (n, t), 'question': q, 'checkpoint': chk})
